select

from advisor
where 1 = 1

    and (
        advisor_code like concat('%', #{q.keyword}, '%')
        or advisor_name like concat('%', #{q.keyword}, '%')
        or advisor_type like concat('%', #{q.keyword}, '%')
    )


    and enabled = #{q.enabled}


    and advisor_type = #{q.advisorType}

order by updated_at desc, id desc
limit #{q.offset}, #{q.pageSize}

